-- modify "challenges" table
ALTER TABLE "challenges" DROP COLUMN "subject_tag", ADD COLUMN "subject_skill_id" uuid NULL, ADD COLUMN "subject_concept_id" uuid NULL;
-- create "concepts" table
CREATE TABLE "concepts" ("id" uuid NOT NULL, "name" character varying NOT NULL, "parent_id" uuid NULL, PRIMARY KEY ("id"), CONSTRAINT "concepts_concepts_parent" FOREIGN KEY ("parent_id") REFERENCES "concepts" ("id") ON UPDATE NO ACTION ON DELETE SET NULL);
-- modify "content_nodes" table
ALTER TABLE "content_nodes" DROP COLUMN "skill", DROP COLUMN "concept";
-- create "content_node_concepts" table
CREATE TABLE "content_node_concepts" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "linked_at" timestamptz NOT NULL, "content_node_id" uuid NOT NULL, "concept_id" uuid NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "content_node_concepts_concepts_concept" FOREIGN KEY ("concept_id") REFERENCES "concepts" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "content_node_concepts_content_nodes_content_node" FOREIGN KEY ("content_node_id") REFERENCES "content_nodes" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION);
-- create index "contentnodeconcept_content_node_id_concept_id" to table: "content_node_concepts"
CREATE UNIQUE INDEX "contentnodeconcept_content_node_id_concept_id" ON "content_node_concepts" ("content_node_id", "concept_id");
-- create "skills" table
CREATE TABLE "skills" ("id" uuid NOT NULL, "name" character varying NOT NULL, "parent_id" uuid NULL, PRIMARY KEY ("id"), CONSTRAINT "skills_skills_parent" FOREIGN KEY ("parent_id") REFERENCES "skills" ("id") ON UPDATE NO ACTION ON DELETE SET NULL);
-- create "content_node_skills" table
CREATE TABLE "content_node_skills" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "linked_at" timestamptz NOT NULL, "content_node_id" uuid NOT NULL, "skill_id" uuid NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "content_node_skills_content_nodes_content_node" FOREIGN KEY ("content_node_id") REFERENCES "content_nodes" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "content_node_skills_skills_skill" FOREIGN KEY ("skill_id") REFERENCES "skills" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION);
-- create index "contentnodeskill_content_node_id_skill_id" to table: "content_node_skills"
CREATE UNIQUE INDEX "contentnodeskill_content_node_id_skill_id" ON "content_node_skills" ("content_node_id", "skill_id");
-- modify "exercises" table
ALTER TABLE "exercises" DROP COLUMN "skill_tags";
-- create "exercise_concepts" table
CREATE TABLE "exercise_concepts" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "linked_at" timestamptz NOT NULL, "exercise_id" uuid NOT NULL, "concept_id" uuid NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "exercise_concepts_concepts_concept" FOREIGN KEY ("concept_id") REFERENCES "concepts" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "exercise_concepts_exercises_exercise" FOREIGN KEY ("exercise_id") REFERENCES "exercises" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION);
-- create index "exerciseconcept_exercise_id_concept_id" to table: "exercise_concepts"
CREATE UNIQUE INDEX "exerciseconcept_exercise_id_concept_id" ON "exercise_concepts" ("exercise_id", "concept_id");
-- create "exercise_skills" table
CREATE TABLE "exercise_skills" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "linked_at" timestamptz NOT NULL, "exercise_id" uuid NOT NULL, "skill_id" uuid NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "exercise_skills_exercises_exercise" FOREIGN KEY ("exercise_id") REFERENCES "exercises" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "exercise_skills_skills_skill" FOREIGN KEY ("skill_id") REFERENCES "skills" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION);
-- create index "exerciseskill_exercise_id_skill_id" to table: "exercise_skills"
CREATE UNIQUE INDEX "exerciseskill_exercise_id_skill_id" ON "exercise_skills" ("exercise_id", "skill_id");
